 * Policy implementations: a token bucket and a sliding window.
 * Each keeps one independent state per key, created lazily the first
 * time that key reaches the policy.
 */

export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    this.max = capacity * per
    this.states = new Map() // key -> { num: BigInt (tokens * per), lastTick: BigInt }
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { num: this.max, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      let num = state.num + this.refill * delta
      if (num > this.max) num = this.max
      state.num = num
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.num >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.num -= this.per
  }
}

export class Window {
  constructor(limit, span) {
    this.limit = limit // BigInt
    this.span = span // BigInt
    this.states = new Map() // key -> array of BigInt ticks, ascending
  }

  advance(key, tick) {
    let arr = this.states.get(key)
    if (!arr) {
      arr = []
      this.states.set(key, arr)
      return
    }
    const threshold = tick - this.span
    let start = 0
    while (start < arr.length && arr[start] <= threshold) start++
    if (start > 0) arr.splice(0, start)
  }

  allow(key) {
    const arr = this.states.get(key)
    return BigInt(arr.length) < this.limit
  }

  record(key) {
    const arr = this.states.get(key)
    arr.push(this._lastTick)
  }

  // record needs the tick; set it just before calling record via advance's
  // last-seen tick. We track it separately to keep the API simple.
  setTick(tick) {
    this._lastTick = tick
  }
}
"}

