/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { simulate, ParseError } from './parse.js'

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function main() {
  if (process.argv.length !== 3) usageError()
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') usageError()

  const input = readFileSync(0, 'utf8')

  let result
  try {
    result = simulate(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out
  if (mode === 'replay') {
    out = result.replayLines.map((l) => l + '\n').join('')
  } else {
    const { perKey, totalAllowed, totalDenied } = result.summary
    const keys = [...perKey.keys()].sort()
    let s = ''
    for (const key of keys) {
      const stat = perKey.get(key)
      s += `${key} allowed=${stat.allowed} denied=${stat.denied}\n`
    }
    s += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    out = s
  }

  process.stdout.write(out)
  process.exit(0)
}

